create extension if not exists pgcrypto;
create table if not exists public.projects (id uuid primary key default gen_random_uuid(), user_id uuid not null, name varchar not null, description text, color varchar default '#3B82F6', icon varchar default 'folder', total_size bigint default 0, file_count integer default 0, created_at timestamptz default now(), updated_at timestamptz default now());
create table if not exists public.folders (id uuid primary key default gen_random_uuid(), project_id uuid references public.projects on delete cascade not null, name varchar not null, parent_id uuid references public.folders on delete cascade, created_at timestamptz default now(), updated_at timestamptz default now());
create table if not exists public.files (id uuid primary key default gen_random_uuid(), project_id uuid references public.projects on delete cascade not null, folder_id uuid references public.folders on delete cascade, name varchar not null, size bigint default 0, mime_type varchar, extension varchar, storage_path text not null, thumbnail_path text, checksum varchar, is_trashed boolean default false, trashed_at timestamptz, last_accessed_at timestamptz, created_at timestamptz default now(), updated_at timestamptz default now());
create table if not exists public.shared_links (id uuid primary key default gen_random_uuid(), file_id uuid references public.files on delete cascade not null, token varchar unique not null, expires_at timestamptz, download_count integer default 0, created_by uuid not null, created_at timestamptz default now());
create table if not exists public.activity_logs (id uuid primary key default gen_random_uuid(), user_id uuid not null, project_id uuid references public.projects on delete cascade, action varchar not null, file_id uuid references public.files on delete set null, details jsonb, created_at timestamptz default now());
insert into storage.buckets (id, name, public, file_size_limit) values ('drive-files', 'drive-files', false, 5368709120), ('thumbnails', 'thumbnails', false, 1048576) on conflict (id) do nothing;
